// axi4_lite_regs
// Four 32-bit read/write registers behind an AXI4-Lite subordinate port.
// Interface: interface_spec.md. Implementation plan: microarchitecture.md.
//   * READY is a function of state only (no combinational path from VALID).
//   * AW and W are captured in holding registers; the write fires on the edge
//     that completes the pair: do_write = (aw_held | aw_hs) & (w_held | w_hs).
//   * One outstanding transaction per direction; B and R are registered and
//     valid one cycle after the request completes.
//   * Unmapped (misaligned) addresses are answered with SLVERR.

module axi4_lite_regs #(
    parameter integer ADDR_WIDTH = 4,
    parameter integer DATA_WIDTH = 32
) (
    input  wire                    aclk,
    input  wire                    aresetn,

    input  wire [ADDR_WIDTH-1:0]   s_axil_awaddr,
    input  wire                    s_axil_awvalid,
    output wire                    s_axil_awready,

    input  wire [DATA_WIDTH-1:0]   s_axil_wdata,
    input  wire [DATA_WIDTH/8-1:0] s_axil_wstrb,
    input  wire                    s_axil_wvalid,
    output wire                    s_axil_wready,

    output wire [1:0]              s_axil_bresp,
    output wire                    s_axil_bvalid,
    input  wire                    s_axil_bready,

    input  wire [ADDR_WIDTH-1:0]   s_axil_araddr,
    input  wire                    s_axil_arvalid,
    output wire                    s_axil_arready,

    output wire [DATA_WIDTH-1:0]   s_axil_rdata,
    output wire [1:0]              s_axil_rresp,
    output wire                    s_axil_rvalid,
    input  wire                    s_axil_rready
);

    localparam integer STRB_WIDTH  = DATA_WIDTH / 8;
    localparam [1:0]   RESP_OKAY   = 2'b00;
    localparam [1:0]   RESP_SLVERR = 2'b10;

    // ------------------------------------------------------------------
    // State
    // ------------------------------------------------------------------
    reg                    aw_held;
    reg                    w_held;
    reg                    bvalid_q;
    reg  [1:0]             bresp_q;
    reg                    rvalid_q;
    reg  [1:0]             rresp_q;
    reg  [DATA_WIDTH-1:0]  rdata_q;

    // Holding registers: datapath, not reset (their "held" flags are).
    reg  [ADDR_WIDTH-1:0]  aw_addr_q;
    reg  [DATA_WIDTH-1:0]  w_data_q;
    reg  [STRB_WIDTH-1:0]  w_strb_q;

    // Register file: separate flops, no memory inference.
    reg  [DATA_WIDTH-1:0]  reg0;
    reg  [DATA_WIDTH-1:0]  reg1;
    reg  [DATA_WIDTH-1:0]  reg2;
    reg  [DATA_WIDTH-1:0]  reg3;

    // ------------------------------------------------------------------
    // Handshakes (READY depends on state only)
    // ------------------------------------------------------------------
    assign s_axil_awready = !aw_held && !bvalid_q;
    assign s_axil_wready  = !w_held  && !bvalid_q;
    assign s_axil_arready = !rvalid_q;

    wire aw_hs = s_axil_awvalid && s_axil_awready;
    wire w_hs  = s_axil_wvalid  && s_axil_wready;
    wire ar_hs = s_axil_arvalid && s_axil_arready;

    wire do_write = (aw_held || aw_hs) && (w_held || w_hs);

    // Address and data used by the write: held copy if present, else live bus.
    wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
    wire [DATA_WIDTH-1:0] wr_data = w_held  ? w_data_q  : s_axil_wdata;
    wire [STRB_WIDTH-1:0] wr_strb = w_held  ? w_strb_q  : s_axil_wstrb;
    wire [1:0]            wr_idx  = wr_addr[3:2];

    // Address decode: mapped when word aligned and within 0x0..0xC.
    wire wr_mapped = (wr_addr[1:0] == 2'b00) &&
                     ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});
    wire ar_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                     ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});

    // Byte-enable mask: byte n of the word is written when wstrb[n] is set.
    wire [DATA_WIDTH-1:0] wr_mask;
    genvar g;
    generate
        for (g = 0; g < STRB_WIDTH; g = g + 1) begin : g_wr_mask
            assign wr_mask[8*g +: 8] = {8{wr_strb[g]}};
        end
    endgenerate

    // ------------------------------------------------------------------
    // Write channel control and B response
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held  <= 1'b0;
            w_held   <= 1'b0;
            bvalid_q <= 1'b0;
            bresp_q  <= RESP_OKAY;
        end else begin
            if (do_write) begin
                aw_held  <= 1'b0;
                w_held   <= 1'b0;
                bvalid_q <= 1'b1;
                bresp_q  <= wr_mapped ? RESP_OKAY : RESP_SLVERR;
            end else begin
                if (aw_hs) begin
                    aw_held <= 1'b1;
                end
                if (w_hs) begin
                    w_held <= 1'b1;
                end
                if (bvalid_q && s_axil_bready) begin
                    bvalid_q <= 1'b0;
                end
            end
        end
    end

    // Holding registers (datapath, no reset).
    always @(posedge aclk) begin
        if (aw_hs) begin
            aw_addr_q <= s_axil_awaddr;
        end
        if (w_hs) begin
            w_data_q <= s_axil_wdata;
            w_strb_q <= s_axil_wstrb;
        end
    end

    // ------------------------------------------------------------------
    // Register file
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            reg0 <= {DATA_WIDTH{1'b0}};
            reg1 <= {DATA_WIDTH{1'b0}};
            reg2 <= {DATA_WIDTH{1'b0}};
            reg3 <= {DATA_WIDTH{1'b0}};
        end else if (do_write && wr_mapped) begin
            case (wr_idx)
                2'd0:    reg0 <= (reg0 & ~wr_mask) | (wr_data & wr_mask);
                2'd1:    reg1 <= (reg1 & ~wr_mask) | (wr_data & wr_mask);
                2'd2:    reg2 <= (reg2 & ~wr_mask) | (wr_data & wr_mask);
                default: reg3 <= (reg3 & ~wr_mask) | (wr_data & wr_mask);
            endcase
        end
    end

    // ------------------------------------------------------------------
    // Read channel and R response
    // ------------------------------------------------------------------
    reg [DATA_WIDTH-1:0] rd_sel;
    always @(*) begin
        case (s_axil_araddr[3:2])
            2'd0:    rd_sel = reg0;
            2'd1:    rd_sel = reg1;
            2'd2:    rd_sel = reg2;
            default: rd_sel = reg3;
        endcase
    end

    always @(posedge aclk) begin
        if (!aresetn) begin
            rvalid_q <= 1'b0;
            rresp_q  <= RESP_OKAY;
            rdata_q  <= {DATA_WIDTH{1'b0}};
        end else if (ar_hs) begin
            rvalid_q <= 1'b1;
            rresp_q  <= ar_mapped ? RESP_OKAY : RESP_SLVERR;
            rdata_q  <= ar_mapped ? rd_sel : {DATA_WIDTH{1'b0}};
        end else if (rvalid_q && s_axil_rready) begin
            rvalid_q <= 1'b0;
        end
    end

    assign s_axil_bvalid = bvalid_q;
    assign s_axil_bresp  = bresp_q;
    assign s_axil_rvalid = rvalid_q;
    assign s_axil_rresp  = rresp_q;
    assign s_axil_rdata  = rdata_q;

    // ------------------------------------------------------------------
    // Design-intent properties (SymbiYosys, read with -formal)
    // ------------------------------------------------------------------
`ifdef FORMAL
    reg f_past_valid = 1'b0;
    always @(posedge aclk) f_past_valid <= 1'b1;

    // Start in reset.
    always @(*) if (!f_past_valid) assume (!aresetn);

    // Manager: VALIDs low in reset; VALID and payload held until READY.
    always @(*) begin
        if (!aresetn) begin
            assume (!s_axil_awvalid);
            assume (!s_axil_wvalid);
            assume (!s_axil_arvalid);
        end
    end

    always @(posedge aclk) begin
        if (f_past_valid && $past(aresetn) && aresetn) begin
            if ($past(s_axil_awvalid && !s_axil_awready)) begin
                assume (s_axil_awvalid);
                assume (s_axil_awaddr == $past(s_axil_awaddr));
            end
            if ($past(s_axil_wvalid && !s_axil_wready)) begin
                assume (s_axil_wvalid);
                assume (s_axil_wdata == $past(s_axil_wdata));
                assume (s_axil_wstrb == $past(s_axil_wstrb));
            end
            if ($past(s_axil_arvalid && !s_axil_arready)) begin
                assume (s_axil_arvalid);
                assume (s_axil_araddr == $past(s_axil_araddr));
            end
        end
    end

    // At most one write open: never both halves held, never a held half
    // while a response is pending.
    always @(*) begin
        if (f_past_valid) begin
            assert (!(aw_held && w_held));
            assert (!(aw_held && bvalid_q));
            assert (!(w_held && bvalid_q));
        end
    end

    always @(posedge aclk) begin
        if (f_past_valid) begin
            if (!$past(aresetn)) begin
                // Responses low after reset.
                assert (!bvalid_q);
                assert (!rvalid_q);
                assert (!aw_held);
                assert (!w_held);
            end else begin
                // B and R hold, with a stable payload, until taken.
                if ($past(bvalid_q && !s_axil_bready)) begin
                    assert (bvalid_q);
                    assert (bresp_q == $past(bresp_q));
                end
                if ($past(rvalid_q && !s_axil_rready)) begin
                    assert (rvalid_q);
                    assert (rresp_q == $past(rresp_q));
                    assert (rdata_q == $past(rdata_q));
                end
                // VALID is high exactly when an accepted request awaits its
                // response (appears one cycle after the request completes).
                assert (bvalid_q == $past(do_write || (bvalid_q && !s_axil_bready)));
                assert (rvalid_q == $past(ar_hs || (rvalid_q && !s_axil_rready)));
                // Response code follows the address policy.
                if ($past(do_write)) begin
                    assert (bresp_q == ($past(wr_mapped) ? RESP_OKAY : RESP_SLVERR));
                end
                if ($past(ar_hs)) begin
                    assert (rresp_q == ($past(ar_mapped) ? RESP_OKAY : RESP_SLVERR));
                    if (!$past(ar_mapped)) begin
                        assert (rdata_q == {DATA_WIDTH{1'b0}});
                    end
                end
            end
        end
    end

    always @(posedge aclk) begin
        if (f_past_valid && aresetn) begin
            cover (bvalid_q && s_axil_bready && bresp_q == RESP_OKAY);
            cover (bvalid_q && s_axil_bready && bresp_q == RESP_SLVERR);
            cover (rvalid_q && s_axil_rready && rresp_q == RESP_OKAY);
            cover (rvalid_q && s_axil_rready && rresp_q == RESP_SLVERR);
            cover (aw_held);
            cover (w_held);
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
