`timescale 1ns / 1ps

// Self-checking directed testbench for axi4_lite_regs.
// Inputs are driven just after the falling edge and sampled 1 ns later, so a
// handshake seen high at the sample point happens on the next rising edge.
// Every task is entered and left in the low phase of the clock.

module axi4_lite_regs_tb;

    reg         aclk;
    reg         aresetn;
    reg  [3:0]  s_axil_awaddr;
    reg         s_axil_awvalid;
    wire        s_axil_awready;
    reg  [31:0] s_axil_wdata;
    reg  [3:0]  s_axil_wstrb;
    reg         s_axil_wvalid;
    wire        s_axil_wready;
    wire [1:0]  s_axil_bresp;
    wire        s_axil_bvalid;
    reg         s_axil_bready;
    reg  [3:0]  s_axil_araddr;
    reg         s_axil_arvalid;
    wire        s_axil_arready;
    wire [31:0] s_axil_rdata;
    wire [1:0]  s_axil_rresp;
    wire        s_axil_rvalid;
    reg         s_axil_rready;

    localparam [1:0] OKAY   = 2'b00;
    localparam [1:0] SLVERR = 2'b10;

    integer        passed;
    integer        failed;
    reg            finished;
    reg [8*64-1:0] nonce;
    reg [31:0]     model [0:3];
    integer        idx;

    axi4_lite_regs #(
        .ADDR_WIDTH(4),
        .DATA_WIDTH(32)
    ) dut (
        .aclk           (aclk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (s_axil_awaddr),
        .s_axil_awvalid (s_axil_awvalid),
        .s_axil_awready (s_axil_awready),
        .s_axil_wdata   (s_axil_wdata),
        .s_axil_wstrb   (s_axil_wstrb),
        .s_axil_wvalid  (s_axil_wvalid),
        .s_axil_wready  (s_axil_wready),
        .s_axil_bresp   (s_axil_bresp),
        .s_axil_bvalid  (s_axil_bvalid),
        .s_axil_bready  (s_axil_bready),
        .s_axil_araddr  (s_axil_araddr),
        .s_axil_arvalid (s_axil_arvalid),
        .s_axil_arready (s_axil_arready),
        .s_axil_rdata   (s_axil_rdata),
        .s_axil_rresp   (s_axil_rresp),
        .s_axil_rvalid  (s_axil_rvalid),
        .s_axil_rready  (s_axil_rready)
    );

    initial aclk = 1'b0;
    always #5 aclk = ~aclk;

    // ------------------------------------------------------------------
    // Checking and verdict
    // ------------------------------------------------------------------
    task check(input cond, input [8*64-1:0] msg);
        begin
            if (cond) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("CHECK FAILED at %0t: %0s", $time, msg);
            end
        end
    endtask

    task finish_tb;
        begin
            if (!finished) begin
                finished = 1'b1;
                $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
                $finish;
            end
        end
    endtask

    function [31:0] merge_tb(input [31:0] old_w, input [31:0] new_w, input [3:0] strb);
        begin
            merge_tb = old_w;
            if (strb[0]) merge_tb[7:0]   = new_w[7:0];
            if (strb[1]) merge_tb[15:8]  = new_w[15:8];
            if (strb[2]) merge_tb[23:16] = new_w[23:16];
            if (strb[3]) merge_tb[31:24] = new_w[31:24];
        end
    endfunction

    // ------------------------------------------------------------------
    // AXI4-Lite write.
    //   mode 0: AW and W together; 1: AW first; 2: W first.
    //   gap   : cycles before the second channel is presented (modes 1, 2).
    //   bdelay: cycles BREADY stays low while BVALID is high.
    // ------------------------------------------------------------------
    task axi_write(input [3:0] addr, input [31:0] data, input [3:0] strb,
                   input integer mode, input integer gap, input integer bdelay,
                   input [1:0] exp_resp);
        integer   cyc;
        integer   lat;
        integer   k;
        reg       aw_done;
        reg       w_done;
        reg [1:0] resp0;
        begin
            aw_done       = 1'b0;
            w_done        = 1'b0;
            cyc           = 0;
            s_axil_bready = 1'b0;
            s_axil_awaddr = addr;
            s_axil_wdata  = data;
            s_axil_wstrb  = strb;
            // Request phase.
            while (!(aw_done && w_done)) begin
                s_axil_awvalid = !aw_done && ((mode != 2) || (cyc >= gap));
                s_axil_wvalid  = !w_done  && ((mode != 1) || (cyc >= gap));
                #1;
                check(!s_axil_bvalid, "no BVALID before the write completes");
                if (s_axil_awvalid && s_axil_awready) aw_done = 1'b1;
                if (s_axil_wvalid && s_axil_wready)   w_done  = 1'b1;
                cyc = cyc + 1;
                if (cyc > 50) begin
                    check(1'b0, "write request timeout");
                    aw_done = 1'b1;
                    w_done  = 1'b1;
                end
                @(negedge aclk);
            end
            // Response phase: we are in the cycle after the completing edge.
            s_axil_awvalid = 1'b0;
            s_axil_wvalid  = 1'b0;
            s_axil_bready  = (bdelay == 0);
            lat = 1;
            #1;
            while (!s_axil_bvalid && lat < 10) begin
                @(negedge aclk);
                lat = lat + 1;
                #1;
            end
            check(s_axil_bvalid, "BVALID follows the write");
            check(lat <= 2, "write latency at most 2 cycles");
            check(!s_axil_awready && !s_axil_wready, "no new write while B pending");
            resp0 = s_axil_bresp;
            check(resp0 == exp_resp, "BRESP matches the address policy");
            for (k = 0; k < bdelay; k = k + 1) begin
                @(negedge aclk);
                #1;
                check(s_axil_bvalid, "BVALID held under backpressure");
                check(s_axil_bresp == resp0, "BRESP stable under backpressure");
                check(!s_axil_awready && !s_axil_wready, "no new write while B pending");
            end
            s_axil_bready = 1'b1;
            @(negedge aclk);
            #1;
            check(!s_axil_bvalid, "BVALID drops after the B handshake");
            check(s_axil_awready && s_axil_wready, "write channel ready after B taken");
        end
    endtask

    // ------------------------------------------------------------------
    // AXI4-Lite read. rdelay: cycles RREADY stays low while RVALID is high.
    // ------------------------------------------------------------------
    task axi_read(input [3:0] addr, input integer rdelay,
                  input [1:0] exp_resp, input [31:0] exp_data);
        integer    cyc;
        integer    lat;
        integer    k;
        reg        ar_done;
        reg [1:0]  resp0;
        reg [31:0] data0;
        begin
            ar_done       = 1'b0;
            cyc           = 0;
            s_axil_rready = 1'b0;
            s_axil_araddr = addr;
            while (!ar_done) begin
                s_axil_arvalid = 1'b1;
                #1;
                check(!s_axil_rvalid, "no RVALID before the read is accepted");
                if (s_axil_arready) ar_done = 1'b1;
                cyc = cyc + 1;
                if (cyc > 50) begin
                    check(1'b0, "read request timeout");
                    ar_done = 1'b1;
                end
                @(negedge aclk);
            end
            s_axil_arvalid = 1'b0;
            s_axil_rready  = (rdelay == 0);
            lat = 1;
            #1;
            while (!s_axil_rvalid && lat < 10) begin
                @(negedge aclk);
                lat = lat + 1;
                #1;
            end
            check(s_axil_rvalid, "RVALID follows the read");
            check(lat <= 2, "read latency at most 2 cycles");
            check(!s_axil_arready, "no new read while R pending");
            resp0 = s_axil_rresp;
            data0 = s_axil_rdata;
            check(resp0 == exp_resp, "RRESP matches the address policy");
            check(data0 == exp_data, "RDATA matches the expected value");
            if (data0 !== exp_data) begin
                $error("  read addr 0x%h: got 0x%h, expected 0x%h", addr, data0, exp_data);
            end
            for (k = 0; k < rdelay; k = k + 1) begin
                @(negedge aclk);
                #1;
                check(s_axil_rvalid, "RVALID held under backpressure");
                check(s_axil_rresp == resp0, "RRESP stable under backpressure");
                check(s_axil_rdata == data0, "RDATA stable under backpressure");
                check(!s_axil_arready, "no new read while R pending");
            end
            s_axil_rready = 1'b1;
            @(negedge aclk);
            #1;
            check(!s_axil_rvalid, "RVALID drops after the R handshake");
            check(s_axil_arready, "read channel ready after R taken");
        end
    endtask

    // Write with expected response from the address policy; update the model.
    task wr(input [3:0] addr, input [31:0] data, input [3:0] strb,
            input integer mode, input integer gap, input integer bdelay);
        reg [1:0] e_resp;
        begin
            e_resp = (addr[1:0] == 2'b00) ? OKAY : SLVERR;
            axi_write(addr, data, strb, mode, gap, bdelay, e_resp);
            if (e_resp == OKAY) begin
                model[addr[3:2]] = merge_tb(model[addr[3:2]], data, strb);
            end
        end
    endtask

    // Read and compare against the model and the address policy.
    task rd(input [3:0] addr, input integer rdelay);
        reg [1:0]  e_resp;
        reg [31:0] e_data;
        begin
            if (addr[1:0] == 2'b00) begin
                e_resp = OKAY;
                e_data = model[addr[3:2]];
            end else begin
                e_resp = SLVERR;
                e_data = 32'h0000_0000;
            end
            axi_read(addr, rdelay, e_resp, e_data);
        end
    endtask

    task rd_all;
        begin
            rd(4'h0, 0);
            rd(4'h4, 0);
            rd(4'h8, 0);
            rd(4'hC, 0);
        end
    endtask

    // ------------------------------------------------------------------
    // Watchdog
    // ------------------------------------------------------------------
    initial begin
        #200000;
        failed = failed + 1;
        $error("WATCHDOG: simulation did not finish");
        finish_tb;
    end

    // ------------------------------------------------------------------
    // Test sequence
    // ------------------------------------------------------------------
    initial begin
        passed   = 0;
        failed   = 0;
        finished = 1'b0;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) begin
            nonce = "none";
        end

        aresetn        = 1'b0;
        s_axil_awaddr  = 4'h0;
        s_axil_awvalid = 1'b0;
        s_axil_wdata   = 32'h0;
        s_axil_wstrb   = 4'h0;
        s_axil_wvalid  = 1'b0;
        s_axil_bready  = 1'b0;
        s_axil_araddr  = 4'h0;
        s_axil_arvalid = 1'b0;
        s_axil_rready  = 1'b0;
        for (idx = 0; idx < 4; idx = idx + 1) model[idx] = 32'h0;

        // 1. Reset.
        repeat (3) @(negedge aclk);
        #1;
        check(!s_axil_bvalid && !s_axil_rvalid, "BVALID/RVALID low in reset");
        aresetn = 1'b1;
        @(negedge aclk);
        #1;
        check(s_axil_awready && s_axil_wready && s_axil_arready, "READY high after reset");
        check(!s_axil_bvalid && !s_axil_rvalid, "BVALID/RVALID low after reset");

        // 2. Reset values.
        rd_all;

        // 3. Write then read every register (AW and W together, back to back).
        wr(4'h0, 32'h0123_4567, 4'hF, 0, 0, 0);
        wr(4'h4, 32'h89AB_CDEF, 4'hF, 0, 0, 0);
        wr(4'h8, 32'hDEAD_BEEF, 4'hF, 0, 0, 0);
        wr(4'hC, 32'hCAFE_F00D, 4'hF, 0, 0, 0);
        rd_all;

        // 4. WSTRB partial writes.
        wr(4'h4, 32'h1122_3344, 4'hF, 0, 0, 0);
        wr(4'h4, 32'hAAAA_AAAA, 4'b0001, 0, 0, 0);
        rd(4'h4, 0);
        wr(4'h4, 32'hBBBB_BBBB, 4'b0110, 0, 0, 0);
        rd(4'h4, 0);
        wr(4'h4, 32'hCCCC_CCCC, 4'b1000, 0, 0, 0);
        rd(4'h4, 0);
        wr(4'h4, 32'hFFFF_FFFF, 4'b0000, 0, 0, 0);   // no change, still OKAY
        rd(4'h4, 0);
        wr(4'h8, 32'h5566_7788, 4'b1010, 0, 0, 0);
        rd(4'h8, 0);
        check(model[1] == 32'hCCBB_BBAA, "TB model: byte-merge reference value");

        // 5. AW/W ordering: AW first, W first, both together.
        wr(4'h0, 32'hA0A0_0001, 4'hF, 1, 1, 0);
        rd(4'h0, 0);
        wr(4'h4, 32'hA0A0_0002, 4'hF, 1, 4, 0);
        rd(4'h4, 0);
        wr(4'h8, 32'hA0A0_0003, 4'hF, 2, 1, 0);
        rd(4'h8, 0);
        wr(4'hC, 32'hA0A0_0004, 4'hF, 2, 4, 0);
        rd(4'hC, 0);
        wr(4'h0, 32'hA0A0_0005, 4'hF, 0, 0, 0);
        rd(4'h0, 0);
        wr(4'h4, 32'h0000_9900, 4'b0010, 2, 2, 0);   // partial, W first
        rd(4'h4, 0);

        // 6. B and R backpressure.
        wr(4'hC, 32'h0BAD_CAFE, 4'hF, 0, 0, 3);
        rd(4'hC, 4);
        wr(4'h8, 32'h7777_1111, 4'hF, 1, 2, 1);
        rd(4'h8, 1);
        wr(4'h0, 32'h4242_4242, 4'hF, 2, 1, 5);
        rd(4'h0, 2);

        // 7. Back-to-back transactions with always-ready manager.
        wr(4'h0, 32'h1000_00F0, 4'hF, 0, 0, 0);
        wr(4'h4, 32'h2000_00F1, 4'hF, 0, 0, 0);
        wr(4'h8, 32'h3000_00F2, 4'hF, 0, 0, 0);
        wr(4'hC, 32'h4000_00F3, 4'hF, 0, 0, 0);
        rd(4'h0, 0);
        rd(4'h4, 0);
        rd(4'h8, 0);
        rd(4'hC, 0);

        // 8. SLVERR policy for unmapped (misaligned) addresses.
        wr(4'h5, 32'hFFFF_FFFF, 4'hF, 0, 0, 0);
        wr(4'hE, 32'hEEEE_EEEE, 4'hF, 2, 2, 2);
        wr(4'h1, 32'h1111_1111, 4'hF, 1, 1, 0);
        wr(4'h3, 32'h3333_3333, 4'hF, 0, 0, 1);
        rd_all;                                       // no register changed
        rd(4'h6, 0);
        rd(4'hF, 3);
        rd(4'h1, 0);
        rd(4'h2, 1);

        // 9. Read and write in flight at the same time.
        fork
            wr(4'h0, 32'h1357_9BDF, 4'hF, 1, 2, 2);
            rd(4'hC, 1);
        join
        rd(4'h0, 0);
        fork
            wr(4'h4, 32'h2468_ACE0, 4'hF, 0, 0, 0);
            rd(4'h8, 0);
        join
        rd(4'h4, 0);

        // 10. A half-accepted write (AW without W) is discarded by reset.
        s_axil_bready  = 1'b0;
        s_axil_awaddr  = 4'h4;
        s_axil_awvalid = 1'b1;
        #1;
        check(s_axil_awready, "AWREADY for a lone AW");
        @(negedge aclk);
        s_axil_awvalid = 1'b0;
        #1;
        check(!s_axil_awready && s_axil_wready, "AW held while W is awaited");
        check(!s_axil_bvalid, "no B for a half-accepted write");
        aresetn = 1'b0;
        repeat (2) @(negedge aclk);
        #1;
        check(!s_axil_bvalid && !s_axil_rvalid, "BVALID/RVALID low in reset");
        aresetn = 1'b1;
        @(negedge aclk);
        #1;
        check(s_axil_awready && s_axil_wready && s_axil_arready, "half write dropped by reset");
        for (idx = 0; idx < 4; idx = idx + 1) model[idx] = 32'h0;
        rd_all;                                       // reset values again
        wr(4'h8, 32'hA5A5_0F0F, 4'hF, 2, 3, 0);       // lone W must wait for AW
        rd_all;

        finish_tb;
    end

endmodule
